package tui

import (
	"encoding/json"
	"fmt"
	"os"
	"slices"
	"testing"
)

// The golden file is generated by driving the upstream ScrollView through the
// same scripted layout/scroll sequence (tui/testdata/scrollview/generate.mjs,
// pi v1.5.2 b4afdddf packages/tui/src/components/scroll-view.ts) and recording
// its observable state after each step.

type scrollViewStep struct {
	Op            string   `json:"op"`
	ContentHeight int      `json:"contentHeight"`
	ViewportHt    int      `json:"viewportHeight"`
	Lines         int      `json:"lines"`
	Top           int      `json:"top"`
	DisableFollow bool     `json:"disableFollow"`
	Value         any      `json:"value"`
	Width         int      `json:"width"`
	Result        []string `json:"result"`
}

type scrollViewState struct {
	ScrollTop        int    `json:"scrollTop"`
	FollowingEnd     bool   `json:"followingEnd"`
	ViewportHeight   int    `json:"viewportHeight"`
	Scrollbar        string `json:"scrollbar"`
	ScrollbarVisible bool   `json:"scrollbarVisible"`
	ScrollbarActive  bool   `json:"scrollbarActive"`
	Renders          int    `json:"renders"`
	Result           any    `json:"result"`
}

type scrollViewCase struct {
	Spec struct {
		Options struct {
			Follow     string `json:"follow"`
			Primary    bool   `json:"primary"`
			Overscroll string `json:"overscroll"`
			Scrollbar  string `json:"scrollbar"`
		} `json:"options"`
		Lines []string         `json:"lines"`
		Steps []scrollViewStep `json:"steps"`
	} `json:"spec"`
	Steps []scrollViewState `json:"steps"`
}

// TestScrollViewAgainstUpstreamGolden replays the upstream scroll state machine.
func TestScrollViewAgainstUpstreamGolden(t *testing.T) {
	data, err := os.ReadFile("testdata/scrollview/golden.json")
	if err != nil {
		t.Fatalf("read golden: %v", err)
	}
	var golden map[string]scrollViewCase
	if err := json.Unmarshal(data, &golden); err != nil {
		t.Fatalf("parse golden: %v", err)
	}
	labels := make([]string, 0, len(golden))
	for label := range golden {
		labels = append(labels, label)
	}
	sortStrings(labels)

	for _, label := range labels {
		spec := golden[label].Spec
		options := ScrollViewOptions{
			Follow:     spec.Options.Follow,
			Primary:    spec.Options.Primary,
			Overscroll: spec.Options.Overscroll,
			Scrollbar:  ScrollViewScrollbar(spec.Options.Scrollbar),
		}
		child := &scriptedComponent{lines: spec.Lines}
		view := NewScrollView(child, options)
		renders := 0
		requestRender := func() { renders++ }

		for index, step := range spec.Steps {
			var result any
			switch step.Op {
			case "layout":
				view.UpdateLayout(step.ContentHeight, step.ViewportHt, requestRender)
			case "scrollTo":
				view.ScrollTo(step.Top, ScrollToRequest{DisableFollow: step.DisableFollow})
			case "scrollBy":
				result = view.ScrollBy(step.Lines)
			case "start":
				view.ScrollToStart()
			case "end":
				view.ScrollToEnd()
			case "scrollbar":
				value, _ := step.Value.(string)
				view.SetScrollbar(ScrollViewScrollbar(value))
			case "active":
				active, _ := step.Value.(bool)
				view.SetScrollbarActive(active)
			case "render":
				result = view.Render(step.Width)
			default:
				t.Fatalf("%s step %d: unknown op %q", label, index, step.Op)
			}

			want := golden[label].Steps[index]
			if view.ScrollTop() != want.ScrollTop {
				t.Fatalf("%s step %d scrollTop = %d, want %d", label, index, view.ScrollTop(), want.ScrollTop)
			}
			if view.IsFollowingEnd() != want.FollowingEnd {
				t.Fatalf("%s step %d followingEnd = %v, want %v", label, index, view.IsFollowingEnd(), want.FollowingEnd)
			}
			if view.ViewportHeight() != want.ViewportHeight {
				t.Fatalf("%s step %d viewportHeight = %d, want %d", label, index, view.ViewportHeight(), want.ViewportHeight)
			}
			if string(view.Scrollbar()) != want.Scrollbar {
				t.Fatalf("%s step %d scrollbar = %q, want %q", label, index, view.Scrollbar(), want.Scrollbar)
			}
			if view.IsScrollbarVisible() != want.ScrollbarVisible {
				t.Fatalf("%s step %d scrollbarVisible = %v, want %v", label, index, view.IsScrollbarVisible(), want.ScrollbarVisible)
			}
			if view.IsScrollbarActive() != want.ScrollbarActive {
				t.Fatalf("%s step %d scrollbarActive = %v, want %v", label, index, view.IsScrollbarActive(), want.ScrollbarActive)
			}
			if renders != want.Renders {
				t.Fatalf("%s step %d renders = %d, want %d", label, index, renders, want.Renders)
			}
			if err := compareScrollResult(label, index, result, want.Result); err != nil {
				t.Fatal(err)
			}
		}
	}
}

// compareScrollResult compares the returned value of scrollBy (a number) and
// render (lines), which the fixture records as a number or an array.
func compareScrollResult(label string, index int, got any, want any) error {
	switch wantValue := want.(type) {
	case nil:
		return nil
	case float64:
		gotNumber, ok := got.(int)
		if !ok || float64(gotNumber) != wantValue {
			return fmt.Errorf("%s step %d result = %v, want %v", label, index, got, wantValue)
		}
		return nil
	case []any:
		gotLines, ok := got.([]string)
		if !ok {
			return fmt.Errorf("%s step %d result = %v, want lines %v", label, index, got, wantValue)
		}
		wantLines := make([]string, len(wantValue))
		for i, line := range wantValue {
			wantLines[i] = line.(string)
		}
		if !slices.Equal(gotLines, wantLines) {
			return fmt.Errorf("%s step %d lines:\n got %q\nwant %q", label, index, gotLines, wantLines)
		}
		return nil
	default:
		return fmt.Errorf("%s step %d: unexpected golden result type %T", label, index, want)
	}
}
